-- One preparation owner and original Command; immutable legacy payloads stay exact.
ALTER TABLE product_command_admission DROP CONSTRAINT product_command_admission_command_kind_check;
ALTER TABLE product_command_admission ADD CONSTRAINT product_command_admission_command_kind_check CHECK (command_kind IN ('CREATE_FACTOR_STUDY_GRANT', 'CONTINUE_FACTOR_STUDY', 'PREPARE_FACTOR_RESEARCH', 'CANCEL_FACTOR_RESEARCH_PREPARATION', 'STAGE_FACTOR_STUDY', 'WITHDRAW_FACTOR_STUDY', 'CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'WITHDRAW_FACTOR_PROPOSAL', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_STRATEGY_DRAFT', 'PUBLISH_PRIVATE_STRATEGY_REVISION', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY', 'PREPARE_STRATEGY_RESEARCH', 'CANCEL_STRATEGY_RESEARCH_PREPARATION'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_command_kind_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_command_kind_check CHECK (command_kind IN ('CREATE_FACTOR_STUDY_GRANT', 'CONTINUE_FACTOR_STUDY', 'PREPARE_FACTOR_RESEARCH', 'CANCEL_FACTOR_RESEARCH_PREPARATION', 'STAGE_FACTOR_STUDY', 'WITHDRAW_FACTOR_STUDY', 'CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'WITHDRAW_FACTOR_PROPOSAL', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_STRATEGY_DRAFT', 'PUBLISH_PRIVATE_STRATEGY_REVISION', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY', 'PREPARE_STRATEGY_RESEARCH', 'CANCEL_STRATEGY_RESEARCH_PREPARATION'));

ALTER TABLE research_preparation
    ADD COLUMN preparation_kind TEXT NOT NULL DEFAULT 'FACTOR_RESEARCH',
    ADD CONSTRAINT research_preparation_kind_check
        CHECK (preparation_kind IN ('FACTOR_RESEARCH','STRATEGY_RESEARCH')),
    ADD CONSTRAINT research_preparation_kind_contract_check CHECK ((
        (preparation_kind='FACTOR_RESEARCH'
            AND accepted_payload::jsonb->>'contract'='ONLYALPHA_ACCEPTED_RESEARCH_PREPARATION_V1')
        OR (preparation_kind='STRATEGY_RESEARCH'
            AND accepted_payload::jsonb->>'contract'='ONLYALPHA_ACCEPTED_STRATEGY_RESEARCH_PREPARATION_V1')
    ) IS TRUE);

CREATE FUNCTION research_preparation_preserve_kind() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.preparation_kind IS DISTINCT FROM OLD.preparation_kind THEN
        RAISE EXCEPTION 'Research preparation kind is immutable';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER research_preparation_kind_immutable BEFORE UPDATE ON research_preparation
    FOR EACH ROW EXECUTE FUNCTION research_preparation_preserve_kind();

-- The accepted operation remains the existing global Command receipt's effect.
CREATE FUNCTION research_preparation_kind_relation_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE expected_kind TEXT;
BEGIN
    expected_kind := CASE NEW.preparation_kind
        WHEN 'FACTOR_RESEARCH' THEN 'PREPARE_FACTOR_RESEARCH'
        WHEN 'STRATEGY_RESEARCH' THEN 'PREPARE_STRATEGY_RESEARCH' END;
    IF NOT EXISTS (
        SELECT 1 FROM public.product_command_admission a
        JOIN public.product_command_receipt r ON r.command_id=a.command_id
        WHERE a.command_id=NEW.command_id AND a.command_kind=expected_kind
            AND r.command_kind=a.command_kind AND r.command_fingerprint=a.command_fingerprint
            AND r.outcome_kind='RESEARCH_PREPARATION_OPERATION'
            AND r.outcome_id=NEW.accepted_fingerprint
    ) THEN RAISE EXCEPTION 'RESEARCH_PREPARATION_KIND_RELATION_CORRUPT'; END IF;
    RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER research_preparation_kind_relation
    AFTER INSERT OR UPDATE ON research_preparation DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION research_preparation_kind_relation_guard();
